def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = dict(jumps)

    # Resolve every possible landing cell to its final cell.
    resolved = list(range(n + 1))
    for cell in jump:
        path = []
        current = cell
        while current in jump:
            path.append(current)
            current = jump[current]
        for visited in path:
            resolved[visited] = current

    # Build the transition graph for states reachable from cell 0.
    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    seen = {0}
    queue = deque([0])

    while queue:
        state = queue.popleft()
        if state == n:
            continue

        destinations = []
        for roll in range(1, m + 1):
            landing = state + roll
            if landing > n:
                landing = 2 * n - landing
            destination = resolved[landing]
            destinations.append(destination)
            reverse[destination].append(state)
            if destination not in seen:
                seen.add(destination)
                queue.append(destination)

        transitions[state] = destinations

    # Every reachable state must have a path to the terminal state.
    can_finish = {n}
    queue = deque([n])
    while queue:
        state = queue.popleft()
        for previous in reverse[state]:
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if not seen.issubset(can_finish):
        return None

    states = list(transitions)
    index = {state: i for i, state in enumerate(states)}
    size = len(states)

    # m * E[state] - sum(E[destination]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for state, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for destination in transitions[state]:
            if destination != n:
                matrix[i][index[destination]] -= 1

    # Fraction-free Gaussian elimination (Bareiss algorithm).
    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        for i in range(k + 1, size):
            factor = matrix[i][k]
            for j in range(k + 1, size + 1):
                matrix[i][j] = (
                    matrix[i][j] * pivot - factor * matrix[k][j]
                ) // previous_pivot
            matrix[i][k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
